<?php require __DIR__.'/../config.php';header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){echo json_encode(['ok'=>false,'message'=>'Invalid request']);exit;}try{check_csrf();if(!empty($_POST['website']))throw new RuntimeException('Spam blocked.');$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($message)<10)throw new RuntimeException('Please enter valid contact details and a message.');$st=db()->prepare('INSERT INTO messages(name,email,phone,subject,message) VALUES(?,?,?,?,?)');$st->execute([$name,$email,$phone,$subject,$message]);$to=setting('site_email',ADMIN_EMAIL);$sub='Portfolio enquiry: '.($subject?:'New message');$body="Name: $name\nEmail: $email\nPhone: $phone\n\n$message";@mail($to,$sub,$body,'From: '.$to."\r\nReply-To: ".$email);echo json_encode(['ok'=>true,'message'=>'Thanks! Your message has been received.']);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()]);}
